SELECT receive_id, receive_no, receive_type, supplier_id, purchase_id, item_id, product_id, sku_id, receive_quantity, receive_weight, unit_price, receive_by, receive_time, status, receive_flag, remark, create_time, update_time FROM t_receive
AND deleted_flag = #{queryForm.deletedFlag}
AND receive_type = #{queryForm.receiveType}
AND supplier_id = #{queryForm.supplierId}
AND purchase_id = #{queryForm.purchaseId}
AND item_id = #{queryForm.itemId}
AND status = #{queryForm.status}
ORDER BY receive_id DESC

